async function (vars) {
    vars.SourceSystemResult = (await getSystem({ Id: vars.SourceSystemId })).value;
},
async function (vars) {
    if (vars.SourceSystemResult.length === 0) {
        vars.SourceSystem = await createSystem({
            Id: vars.SourceSystemId,
            Name: vars.SourceSystemId,
            Description: "Source System for " + vars.AppName + "." + vars.AppType,
            IsPublic: false
        });
    } else {
        vars.SourceSystem = vars.SourceSystemResult[0];
    }
}
